values.value:
{
  "op_mhp_accessories": [
    {
      "apiName": "mhp_accessories_grid",
      "type": "column-repeater",
      "countApiName": "mhp_accessories_no_of_items",
      "maxColumns": 10,
      "fields": [
        {
          "apiName": "mhp_acc_accessory",
          "label": "ACCESSORY",
          "type": "picklist",
          "required": true,
          "options": [
            "WINCH",
            "WIRE ROPE WITH FASTENERS",
            "LOCK & MANUAL HANDLE"
          ]
        },
        {
          "apiName": "mhp_acc_weight",
          "label": "WEIGHT (KG)",
          "type": "number",
          "required": true,
          "unit": "kg"
        },
        {
          "apiName": "mhp_acc_quantity",
          "label": "QUANTITY",
          "type": "number",
          "required": true,
          "isQuantity": true
        },
        {
          "apiName": "mhp_acc_total_weight",
          "label": "TOTAL WEIGHT (KG)",
          "type": "number",
          "readOnly": true,
          "unit": "kg",
          "isWeightTotal": true,
          "formula": "(mhp_acc_weight || 0 ) * (mhp_acc_quantity || 0) "
        },
        {
          "apiName": "mhp_acc_rate",
          "label": "UNIT RATE",
          "type": "number",
          "unit": "Value"
        },
        {
          "apiName": "op_mhp_acc_unit_price",
          "label": "ACCESSORY UNIT PRICE",
          "isUnitPrice": true,
          "type": "number",
          "readOnly": true,
          "formula": "((mhp_acc_rate || 0) * (mhp_acc_total_weight || 0) )/ (mhp_acc_quantity|| 1)"
        },
        {
          "apiName": "op_mhp_acc_unit_cost",
          "label": "ACCESSORY UNIT COST",
          "isUnitCost": true,
          "type": "number",
          "readOnly": true,
          "formula": "(op_mhp_acc_unit_price || 0)"
        }
      ]
    }
  ]
}
